  function statsBlock(key,value){const title=statNames[key] || names[key] || key;if(Array.isArray(value)){if(!value.length)return `<section class="panel"><h3>${escape(title)}</h3><p>无记录</p></section>`;const keys=[...new Set(value.flatMap(x=>typeof x==='object'?Object.keys(x):[]))];if(!keys.length)return `<section class="panel"><h3>${escape(title)}</h3><p>${value.map(statsValue).join('、')}</p></section>`;return `<section class="panel"><h3>${escape(title)}</h3><div class="table-scroll"><table><thead><tr>${keys.map(k=>`<th>${escape(statNames[k] || names[k] || k)}</th>`).join('')}</tr></thead><tbody>${value.map(row=>`<tr>${keys.map(k=>`<td>${typeof row[k]==='object'?display(row[k]):statsValue(row[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}if(value&&typeof value==='object'){return `<section class="panel"><h3>${escape(title)}</h3>${Object.entries(value).map(([k,v])=>typeof v==='object'?statsBlock(k,v):`<div class="acceptance-stat-row"><span>${escape(statNames[k] || names[k] || k)}</span><strong>${statsValue(v)}</strong></div>`).join('')}</section>`;}return `<div class="kpi"><h3>${escape(title)}</h3><p>${statsValue(value)}</p></div>`;}
